const artGround=ground;ground=function(x,y,t){artGround(x,y,t);const px=x*T,py=y*T,hash=(x*71+y*43)%31;
 if(t==='grass'||t==='tall'){for(let i=0;i<3;i++){const gx=px+(hash+i*11)%29,gy=py+(hash*3+i*7)%27;rr(gx,gy,1,3,'#739850');rr(gx-2,gy-1,1,2,'#8eaf66');}if(hash===7){rr(px+9,py+16,2,4,'#55774a');rr(px+7,py+13,6,3,'#dbd5a0');rr(px+9,py+14,2,1,'#bd9e63');}}
 if(t==='path'){for(const [dx,dy,side]of [[-1,0,'l'],[1,0,'r'],[0,-1,'t'],[0,1,'b']]){const n=map.tiles[y+dy]?.[x+dx];if(['grass','tall','tree'].includes(n)){for(let i=0;i<4;i++){const depth=2+(hash+i)%3;if(side==='l'||side==='r')rr(px+(side==='l'?0:32-depth),py+i*8,depth,6,'#91a86a');else rr(px+i*8,py+(side==='t'?0:32-depth),6,depth,'#91a86a');}}}rr(px+hash%24,py+hash%25,3,2,'#dacc9e');}
 if(t==='water'){rr(px+2,py+18,10,1,'#87c0b9');for(const [dx,dy,side]of [[-1,0,'l'],[1,0,'r'],[0,-1,'t'],[0,1,'b']]){const n=map.tiles[y+dy]?.[x+dx];if(n&&n!=='water'){const vertical=side==='l'||side==='r';rr(px+(side==='r'?29:0),py+(side==='b'?29:0),vertical?3:32,vertical?32:3,'#d3c691');rr(px+(side==='r'?27:side==='l'?3:0),py+(side==='b'?27:side==='t'?3:0),vertical?2:32,vertical?32:2,'#acd2b9');}}if(hash%7===0){rr(px+16,py+10,7,3,'#428e82');rr(px+17,py+9,5,1,'#a0c28c');}}
};
const artInteractionHUD=interactionHUD;interactionHUD=function(){artInteractionHUD();if(!near||dialog||activity)return;const labels={berries:'Berry bush',log:'Fallen timber',crystals:'Moon crystals',chest:'Companion supplies',cache:'Hidden supply chest',fish:'Fishing spot',workbench:'Crafting workbench',plot:'Garden bed',journal:'Adventure journal',bed:'Your bed',seal:'Moonlit door',beacon:'Ancient beacon'};if(labels[near.type]&&!(resourceInfo[near.type]&&(state.cooldowns[near.id]||0)>Date.now()))document.getElementById('near').textContent=labels[near.type];};
// Illustrated field guide makes resources recognizable before the first encounter.
function fieldGuide(){show('Know it when you see it',`<p>Look for these shapes along the trail. Move close to see the name and available action.</p><div class="field-grid">${[['berries','Berry bush','Pick pink berries'],['log','Fallen timber','Chop for wood'],['crystals','Moon crystals','Mine the purple cluster'],['fish','Fishing spot','Cast, wait, then reel'],['workbench','Workbench','Craft inside your home'],['chest','Supplies chest','Collect your friends’ work']].map(([type,title,desc])=>`<div><canvas data-art="${type}" width="96" height="96" aria-label="${title}"></canvas><b>${title}</b><small>${desc}</small></div>`).join('')}</div><div class="actions"><button data-ui="close">Back to exploring</button></div>`,'Field guide');for(const c of document.querySelectorAll('[data-art]')){const sprite=ValleyArt.make(c.dataset.art+'-false',()=>{});c.getContext('2d').drawImage(sprite,0,0);}}
// Warm these six static sprites without changing the visible world.
for(const type of ['berries','log','crystals','fish','workbench','chest']){ctx.save();ctx.translate(-10000,-10000);object({type,id:'guide-'+type,x:0,y:0});ctx.restore();}
const artHelp=help;help=function(){artHelp();const b=document.createElement('button');b.dataset.artguide='true';b.textContent='Illustrated field guide';document.querySelector('.dialog .actions').append(b);};
app.addEventListener('click',e=>{if(e.target.closest('[data-artguide]'))fieldGuide();});
const artEncounter=encounterDialog;encounterDialog=function(){artEncounter();const c=document.getElementById('portrait'),g=c.getContext('2d');g.clearRect(0,0,48,48);g.imageSmoothingEnabled=false;g.drawImage(ValleyArt.make('friend-'+encounter.name+'-0',a=>ValleyArt.creatureSprite(a,encounter.name,0)),-24,-38);};
const artActivities=drawActivities;drawActivities=function(){artActivities();if(!near||dialog||activity)return;const label=near.name||({berries:'Berry bush',log:'Fallen timber',crystals:'Moon crystals',fish:'Fishing spot',chest:'Supplies chest',workbench:'Workbench',plot:'Garden bed',seal:'Moonlit door',beacon:'Ancient beacon'}[near.type]);if(!label)return;ctx.save();ctx.translate(-Math.floor(camera.x),-Math.floor(camera.y));const width=label.length*5.6+12;rr(near.x-width/2,near.y-61,width,15,'#243c32ee');rr(near.x-width/2,near.y-61,width,1,'#cabb87');text(label,near.x,near.y-50,'#fff0c1',9);ctx.restore();};
